import{c as t,Q as s,j as o,m as a}from"./chunks/framework.rWdQudnF.js";const p=JSON.parse('{"title":"系统架构概述","description":"","frontmatter":{"title":"系统架构概述"},"headers":[],"relativePath":"架构师 在线刷题/51CT0题库 章节练习/绪论/系统架构概述.md","filePath":"架构师 在线刷题/51CT0题库 章节练习/绪论/系统架构概述.md","lastUpdated":null}'),r={name:"架构师 在线刷题/51CT0题库 章节练习/绪论/系统架构概述.md"};function n(i,l,g,e,c,u){return s(),o("div",null,[...l[0]||(l[0]=[a('<h1 id="系统架构概述-系统架构设计师" tabindex="-1">系统架构概述(系统架构设计师) <a class="header-anchor" href="#系统架构概述-系统架构设计师" aria-label="Permalink to &quot;系统架构概述(系统架构设计师)&quot;">​</a></h1><blockquote><p>共 17 题 · 题型：单选题 · 来源：51CTO题库</p></blockquote><h2 id="q1-采用以架构为核心的软件开发方法-在建立软件架构的初期-首要任务是选择一个合适的-请作答此空-在此基础上-开发人员通过架构模型-可以获得关于-的理解-为将来的架构实现与演化过程建立了目标。" tabindex="-1">Q1. 采用以架构为核心的软件开发方法，在建立软件架构的初期，首要任务是选择一个合适的（请作答此空），在此基础上，开发人员通过架构模型，可以获得关于（ ）的理解，为将来的架构实现与演化过程建立了目标。 <a class="header-anchor" href="#q1-采用以架构为核心的软件开发方法-在建立软件架构的初期-首要任务是选择一个合适的-请作答此空-在此基础上-开发人员通过架构模型-可以获得关于-的理解-为将来的架构实现与演化过程建立了目标。" aria-label="Permalink to &quot;Q1. 采用以架构为核心的软件开发方法，在建立软件架构的初期，首要任务是选择一个合适的（请作答此空），在此基础上，开发人员通过架构模型，可以获得关于（ ）的理解，为将来的架构实现与演化过程建立了目标。&quot;">​</a></h2><ul><li><strong>A.</strong> 分析模式</li><li><strong>B.</strong> 设计模式</li><li><strong>C.</strong> 架构风格</li><li><strong>D.</strong> 架构标准</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q2-架构是体现在组件中的一个系统的基本组织、它们-及指导它的设计和发展的原则。" tabindex="-1">Q2. 架构是体现在组件中的一个系统的基本组织、它们（ ）及指导它的设计和发展的原则。 <a class="header-anchor" href="#q2-架构是体现在组件中的一个系统的基本组织、它们-及指导它的设计和发展的原则。" aria-label="Permalink to &quot;Q2. 架构是体现在组件中的一个系统的基本组织、它们（ ）及指导它的设计和发展的原则。&quot;">​</a></h2><ul><li><strong>A.</strong> 访问的关系与操作系统的关系</li><li><strong>B.</strong> 调用的关系与运行时的关系</li><li><strong>C.</strong> 位置的关系与组织的关系</li><li><strong>D.</strong> 彼此的关系与环境的关系</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>架构是体现在组件中的一个系统的基本组织、它们彼此的关系与环境的关系及指导它的设计和发展的原则。</p></div></details><h2 id="q3-关于现代大型软件系统的架构设计-下列说法正确的是-。" tabindex="-1">Q3. 关于现代大型软件系统的架构设计，下列说法正确的是（ ）。 <a class="header-anchor" href="#q3-关于现代大型软件系统的架构设计-下列说法正确的是-。" aria-label="Permalink to &quot;Q3. 关于现代大型软件系统的架构设计，下列说法正确的是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 必须严格遵循单一架构风格</li><li><strong>B.</strong> 混合多种架构风格，从不同视角描述系统</li><li><strong>C.</strong> 只能使用C/S或B/S架构风格</li><li><strong>D.</strong> 架构风格的选择与系统规模无关</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" tabindex="-1">Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q4-某企业要开发一个具有较强用户交互功能的应用程序-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q4. 某企业要开发一个具有较强用户交互功能的应用程序，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> SOA风格</li><li><strong>B.</strong> 虚拟机风格</li><li><strong>C.</strong> MVC风格</li><li><strong>D.</strong> 平台/插件风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p><p>A：SOA风格主要用于企业集成<br> B：错误，虚拟机风格用于解释器或专家系统<br> C：正确，MVC风格专门用于用户交互程序的设计<br> D：错误，平台/插件风格主要用于具有插件扩展功能的应用程序</p><p>【教材依据】MVC风格用于用户交互程序的设计。因此本题的正确答案是C。</p><ul><li><strong>SOA 风格</strong>：面向服务，适用于企业系统集成、跨系统调用。</li><li><strong>虚拟机风格</strong>：基于解释器、规则系统，适合规则引擎、脚本语言环境。</li><li><strong>MVC 风格</strong>：明确将交互系统分为 <strong>模型（Model）</strong>、<strong>视图（View）</strong>、<strong>控制器（Controller）</strong>，专为<strong>用户交互频繁、界面多变</strong>的应用设计。</li><li><strong>平台/插件风格</strong>：核心系统 + 插件式扩展，适合 IDE、浏览器等。</li></ul></div></details><h2 id="q5-某系统需要将整个处理过程分解为多个独立的处理步骤-最适合采用的架构风格是-。" tabindex="-1">Q5. 某系统需要将整个处理过程分解为多个独立的处理步骤，最适合采用的架构风格是（ ）。 <a class="header-anchor" href="#q5-某系统需要将整个处理过程分解为多个独立的处理步骤-最适合采用的架构风格是-。" aria-label="Permalink to &quot;Q5. 某系统需要将整个处理过程分解为多个独立的处理步骤，最适合采用的架构风格是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> MVC风格</li><li><strong>B.</strong> 管道-过滤器风格</li><li><strong>C.</strong> C/S风格</li><li><strong>D.</strong> 虚拟机风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><ul><li><strong>A. MVC风格</strong>：适用于用户交互界面，模型-视图-控制器分离，与“处理步骤分解”无关。</li><li><strong>C. C/S风格</strong>：客户端-服务器架构，关注的是分布式部署和请求/响应，不强调处理链路分解。</li><li><strong>D. 虚拟机风格</strong>：适用于解释执行自定义规则或脚本，如解释器、规则引擎，与“步骤分解”不直接匹配</li></ul><p><strong>依赖的是数据</strong>（前一个的输出），但<strong>过滤器本身是独立运行的组件</strong>。这正是管道-过滤器的核心特征</p><ul><li><strong>管道-过滤器风格</strong>： <ul><li>每个<strong>处理步骤</strong>就是一个<strong>过滤器</strong>（Filter）。</li><li>步骤之间通过<strong>管道</strong>（Pipe）连接，前一个步骤的输出作为后一个步骤的输入。</li><li>每个过滤器都是<strong>独立</strong>的组件，可以单独开发、修改、复用。</li><li>经典实例：传统编译器（词法分析 → 语法分析 → 语义分析 → 代码生成）、Linux 命令管道（<code>ps -ef | grep java</code>）。</li></ul></li></ul><p>尽量管道过滤器是依赖前一个步骤的输入，但是他自身的逻辑是独立的。<strong>依赖的是数据，而不是实现</strong>。</p><p><strong>依赖的是数据</strong>（前一个的输出），但<strong>过滤器本身是独立运行的组件</strong>。这正是管道-过滤器的核心特征，而不是它的矛盾点。</p></div></details><h2 id="q6-关于软件架构中动态模型的特征-下列说法正确的是-。" tabindex="-1">Q6. 关于软件架构中动态模型的特征，下列说法正确的是（）。 <a class="header-anchor" href="#q6-关于软件架构中动态模型的特征-下列说法正确的是-。" aria-label="Permalink to &quot;Q6. 关于软件架构中动态模型的特征，下列说法正确的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 主要用于描述系统的静态结构</li><li><strong>B.</strong> 主要用于描述系统构造的具体步骤</li><li><strong>C.</strong> 是对结构或框架模型的补充，描述系统的重新配置或演化</li><li><strong>D.</strong> 仅用于描述系统的性能指标</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q7-下列关于软件架构建模方法的描述-错误的是-。" tabindex="-1">Q7. 下列关于软件架构建模方法的描述，错误的是（）。 <a class="header-anchor" href="#q7-下列关于软件架构建模方法的描述-错误的是-。" aria-label="Permalink to &quot;Q7. 下列关于软件架构建模方法的描述，错误的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 动态模型主要研究系统的重新配置或演化等&quot;大颗粒&quot;行为</li><li><strong>B.</strong> 框架模型比结构模型更侧重描述结构的细节</li><li><strong>C.</strong> 过程模型主要研究构造系统的步骤和过程</li><li><strong>D.</strong> 这四种模型需要有机结合才能完整描述软件架构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><ul><li><strong>A. 正确。</strong> 动态模型确实关注系统运行时的大颗粒行为，如重新配置、演化、通信等，而不是细颗粒的函数调用。</li><li><strong>B. 错误。</strong> 框架模型（Framework Model）通常是从宏观层面定义系统的结构、协作关系或“骨架”，它的<strong>抽象层次更高</strong>，反而<strong>不侧重描述结构的细节</strong>。描述结构细节通常是<strong>结构模型</strong>或详细设计的工作。因此“框架模型比结构模型更侧重细节”这一说法与架构分层的基本原则相悖。</li><li><strong>C. 正确。</strong> 过程模型关注构建系统的步骤、阶段、流程等。</li><li><strong>D. 正确。</strong> 四种模型（结构、框架、动态、过程）是从不同视角描述软件架构，需要有机结合才能完整表达。</li></ul><p><strong>一句话总结：</strong></p><p>框架模型是“骨架”，侧重宏观抽象；结构模型侧重具体组成与细节。<strong>B选项把关系说反了</strong>，所以是错误的。</p></div></details><h2 id="q8-某项目需要重点描述系统的构件、连接件等细节结构-应选择的建模方法是-。" tabindex="-1">Q8. 某项目需要重点描述系统的构件、连接件等细节结构，应选择的建模方法是（）。 <a class="header-anchor" href="#q8-某项目需要重点描述系统的构件、连接件等细节结构-应选择的建模方法是-。" aria-label="Permalink to &quot;Q8. 某项目需要重点描述系统的构件、连接件等细节结构，应选择的建模方法是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> 框架模型</li><li><strong>B.</strong> 结构模型</li><li><strong>C.</strong> 动态模型</li><li><strong>D.</strong> 过程模型</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>“模型结构”属于<strong>软件架构建模方法</strong>中的内容。在软件架构文档中，通常用四种不同的模型从不同视角来描述一个软件架构：</p><table tabindex="0"><thead><tr><th>模型类型</th><th>核心关注点</th><th>包含的关键元素</th></tr></thead><tbody><tr><td><strong>结构模型</strong></td><td><strong>静态组成</strong></td><td>构件、连接件、接口、配置、拓扑结构</td></tr><tr><td><strong>框架模型</strong></td><td><strong>宏观骨架</strong></td><td>整体结构、子系统划分、层次、协作关系</td></tr><tr><td><strong>动态模型</strong></td><td><strong>运行时行为</strong></td><td>状态变化、交互序列、并发、事件、系统演化</td></tr><tr><td><strong>过程模型</strong></td><td><strong>构建过程</strong></td><td>开发步骤、阶段划分、依赖关系</td></tr></tbody></table></div></details><h2 id="q9-架构风格用于gui软件开发-用以构建灵活和可扩展的应用系统等。" tabindex="-1">Q9. （）架构风格用于GUI软件开发，用以构建灵活和可扩展的应用系统等。 <a class="header-anchor" href="#q9-架构风格用于gui软件开发-用以构建灵活和可扩展的应用系统等。" aria-label="Permalink to &quot;Q9. （）架构风格用于GUI软件开发，用以构建灵活和可扩展的应用系统等。&quot;">​</a></h2><ul><li><strong>A.</strong> 管道-过滤器风格</li><li><strong>B.</strong> MVC风格</li><li><strong>C.</strong> SOA风格</li><li><strong>D.</strong> C2风格</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>C2风格用于GU软件开发，用以构建灵活和可扩展的应用系统等。</p></div></details><h2 id="q10-下面不属于微服务架构的三种实现模式之一的是-。" tabindex="-1">Q10. 下面不属于微服务架构的三种实现模式之一的是（）。 <a class="header-anchor" href="#q10-下面不属于微服务架构的三种实现模式之一的是-。" aria-label="Permalink to &quot;Q10. 下面不属于微服务架构的三种实现模式之一的是（）。&quot;">​</a></h2><ul><li><strong>A.</strong> RESTful API模式</li><li><strong>B.</strong> RESTful应用模式</li><li><strong>C.</strong> 集中消息模式</li><li><strong>D.</strong> 分布式消息模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>D</strong></p><p>挺迷的一道题目</p></div></details><h2 id="q11-云架构-cloud-architecture-的主要特点是什么-。" tabindex="-1">Q11. 云架构（Cloud Architecture）的主要特点是什么（ ）。 <a class="header-anchor" href="#q11-云架构-cloud-architecture-的主要特点是什么-。" aria-label="Permalink to &quot;Q11. 云架构（Cloud Architecture）的主要特点是什么（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 低成本运维</li><li><strong>B.</strong> 高安全性</li><li><strong>C.</strong> 高扩展性</li><li><strong>D.</strong> 高可用性</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>C</strong></p></div></details><h2 id="q12-在云架构中-负责将数据复制到每一个处理单元-确保数据同步的组件是-。" tabindex="-1">Q12. 在云架构中，负责将数据复制到每一个处理单元，确保数据同步的组件是（ ）。 <a class="header-anchor" href="#q12-在云架构中-负责将数据复制到每一个处理单元-确保数据同步的组件是-。" aria-label="Permalink to &quot;Q12. 在云架构中，负责将数据复制到每一个处理单元，确保数据同步的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 消息中间件</li><li><strong>B.</strong> 数据中间件</li><li><strong>C.</strong> 处理中间件</li><li><strong>D.</strong> 部署中间件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q13-在云架构中-负责管理用户请求和会话控制-sessions-并决定将请求分配给哪一个处理单元的组件是-。" tabindex="-1">Q13. 在云架构中，负责管理用户请求和会话控制（sessions），并决定将请求分配给哪一个处理单元的组件是（ ）。 <a class="header-anchor" href="#q13-在云架构中-负责管理用户请求和会话控制-sessions-并决定将请求分配给哪一个处理单元的组件是-。" aria-label="Permalink to &quot;Q13. 在云架构中，负责管理用户请求和会话控制（sessions），并决定将请求分配给哪一个处理单元的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 数据中间件</li><li><strong>B.</strong> 消息中间件</li><li><strong>C.</strong> 处理中间件</li><li><strong>D.</strong> 部署中间件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>这个题目也很迷，第一反应选择 C<br> 解析<br> A.数据中间件负责将数据复制到每一个处理单元，实现数据同步，不符合题目描述。<br> B.消息中间件负责管理用户请求和会话控制，并决定将请求分配给哪一个处理单元，符合题目描述。<br> C.处理中间件负责协调不同类型的处理单元，不符合题目描述。<br> D.部署中间件负责处理单元的启动和关闭，以及负载监控，不符合题目描述。因此，正确答案是B.消息中间件。</p></div></details><h2 id="q14-在事件驱动架构-eda-中-负责将不同的事件分发到不同的业务逻辑单元的组件是-。" tabindex="-1">Q14. 在事件驱动架构（EDA）中，负责将不同的事件分发到不同的业务逻辑单元的组件是（ ）。 <a class="header-anchor" href="#q14-在事件驱动架构-eda-中-负责将不同的事件分发到不同的业务逻辑单元的组件是-。" aria-label="Permalink to &quot;Q14. 在事件驱动架构（EDA）中，负责将不同的事件分发到不同的业务逻辑单元的组件是（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 事件队列</li><li><strong>B.</strong> 分发器</li><li><strong>C.</strong> 事件通道</li><li><strong>D.</strong> 事件处理器</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q15-在分层架构中-负责实现业务逻辑的是哪一层-。" tabindex="-1">Q15. 在分层架构中，负责实现业务逻辑的是哪一层（ ）。 <a class="header-anchor" href="#q15-在分层架构中-负责实现业务逻辑的是哪一层-。" aria-label="Permalink to &quot;Q15. 在分层架构中，负责实现业务逻辑的是哪一层（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 表现层</li><li><strong>B.</strong> 业务层</li><li><strong>C.</strong> 持久层</li><li><strong>D.</strong> 数据库层</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details><h2 id="q16-微服务架构的实现模式中-哪种模式通常用于企业内部-背后是一个多功能的应用程序-。" tabindex="-1">Q16. 微服务架构的实现模式中，哪种模式通常用于企业内部，背后是一个多功能的应用程序（ ）。 <a class="header-anchor" href="#q16-微服务架构的实现模式中-哪种模式通常用于企业内部-背后是一个多功能的应用程序-。" aria-label="Permalink to &quot;Q16. 微服务架构的实现模式中，哪种模式通常用于企业内部，背后是一个多功能的应用程序（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> RESTful API模式</li><li><strong>B.</strong> RESTful应用模式</li><li><strong>C.</strong> 集中消息模式</li><li><strong>D.</strong> 分布式消息模式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p><p>解析</p><p>A.RESTful API模式：这种模式通过API提供服务，常见于云服务，不符合题目描述。<br> B.RESTful应用模式：正确。这种模式通过传统的网络协议或应用协议提供服务，背后通常是一个多功能的应用程序，常见于企业内部，符合题目描述。<br> C.集中消息模式：这种模式采用消息代理实现消息队列、负载均衡等功能，不符合题目描述的特征。<br> D.分布式消息模式：这个选项在给定的微服务架构实现模式中并未提及，是一个干扰项。因此，正确答案是B.RESTful应用模式。</p><p>看起来这道题目，是直接先排除了微服务和对外提供服务的选项，然后选了一个大而全的所谓企业系统内部的应用。</p><p>在部分教材的分类中：</p><ul><li><strong>RESTful API模式</strong>：强调对外暴露服务，是“平台”或“能力开放”</li><li><strong>RESTful应用模式</strong>：强调一个完整的应用程序，内部按RESTful风格组织，适合企业内部的业务系统（如ERP、CRM的一个模块）</li></ul></div></details><h2 id="q17-根据架构的定义-以下哪个选项最准确地描述了架构的核心要素-。" tabindex="-1">Q17. 根据架构的定义，以下哪个选项最准确地描述了架构的核心要素（ ）。 <a class="header-anchor" href="#q17-根据架构的定义-以下哪个选项最准确地描述了架构的核心要素-。" aria-label="Permalink to &quot;Q17. 根据架构的定义，以下哪个选项最准确地描述了架构的核心要素（ ）。&quot;">​</a></h2><ul><li><strong>A.</strong> 系统的功能需求和性能指标</li><li><strong>B.</strong> 系统的组件、关系、环境和设计原则</li><li><strong>C.</strong> 系统的开发流程和测试方法</li><li><strong>D.</strong> 系统的用户界面和数据存储结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>正确答案：<strong>B</strong></p></div></details>',53)])])}const h=t(r,[["render",n]]);export{p as __pageData,h as default};
